(()=>{'use strict';class Effects{constructor(){this.particles=[];this.floaters=[];this.trails=[];this.shake=0;this.flash=0;this.holderHits=[];this.holderGlow=0;this.blasts=[]}reset(){this.particles=[];this.floaters=[];this.trails=[];this.shake=0;this.flash=0;this.holderHits=[];this.holderGlow=0;this.blasts=[]}burst(x,y,power=1,type='hit'){const count=Math.min(32,Math.round(7+power*3));for(let i=0;i<count;i++){let a=i*Math.PI*2/count+(Math.random()-.5)*.5,v=.7+Math.random()*2.7;this.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.26+Math.random()*.38,max:.65,size:.025+Math.random()*.05,color:type==='catch'?(i%2?'#fff2a5':'#7fe5c1'):(i%2?'#ffc678':'#f27b50')})}this.shake=Math.max(this.shake,Math.min(1,power*.23));this.particles=this.particles.slice(-160)}explosion(x,y,radius){this.blasts.push({x,y,radius,life:.45,max:.45});this.blasts=this.blasts.slice(-3);this.burst(x,y,8,'hit');this.burst(x,y,8,'catch');this.shake=1.3;this.holderHits.push({x,y,power:2,life:.5,max:.5});this.label(x,y-.25,'BOOM!')}holderImpact(x,y,power=1){this.holderHits.push({x,y,power:Math.min(2,power),life:.24,max:.24});if(this.holderHits.length>16)this.holderHits.shift();this.holderGlow=Math.min(1,.35+power*.15)}trail(x,y){this.trails.push({x,y,life:.15,max:.15});if(this.trails.length>20)this.trails.shift()}label(x,y,text){this.floaters.push({x,y,text,life:.75,max:.75})}update(dt){for(const blast of this.blasts)blast.life-=dt;this.blasts=this.blasts.filter(b=>b.life>0);this.holderGlow=Math.max(0,this.holderGlow-dt*5);for(const hit of this.holderHits)hit.life-=dt;this.holderHits=this.holderHits.filter(hit=>hit.life>0);for(const t of this.trails)t.life-=dt;this.trails=this.trails.filter(t=>t.life>0);for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=3*dt;p.life-=dt}this.particles=this.particles.filter(p=>p.life>0);for(const t of this.floaters){t.y-=dt*.75;t.life-=dt}this.floaters=this.floaters.filter(t=>t.life>0);this.shake=Math.max(0,this.shake-dt*3);this.flash=Math.max(0,this.flash-dt*4)}draw(ctx,cam){ctx.save();for(const blast of this.blasts){const p=cam.toScreen(blast.x,blast.y),age=1-blast.life/blast.max;ctx.globalAlpha=(1-age)*.8;ctx.strokeStyle='#ffb34e';ctx.lineWidth=Math.max(2,cam.scale*.08*(1-age));ctx.beginPath();ctx.arc(p.x,p.y,Math.max(1,blast.radius*cam.scale*age),0,Math.PI*2);ctx.stroke();ctx.globalAlpha=(1-age)*.3;ctx.fillStyle='#fff2bb';ctx.fill()}ctx.globalAlpha=1;
for(const hit of this.holderHits){const point=cam.toScreen(hit.x,hit.y),age=1-hit.life/hit.max,r=cam.scale*(.055+age*.17),alpha=Math.max(0,1-age);ctx.globalAlpha=alpha;ctx.lineCap='round';ctx.lineWidth=Math.max(1.2,cam.scale*.016);ctx.strokeStyle='#fffbe6';for(let i=0;i<6;i++){const a=i*Math.PI/3+.28;ctx.beginPath();ctx.moveTo(point.x+Math.cos(a)*r*.50,point.y+Math.sin(a)*r*.50);ctx.lineTo(point.x+Math.cos(a)*r,point.y+Math.sin(a)*r);ctx.stroke()}ctx.globalAlpha=alpha*.65;ctx.strokeStyle='#ffd783';ctx.beginPath();ctx.ellipse(point.x,point.y,r*.58,r*.35,0,0,Math.PI*2);ctx.stroke()}
ctx.globalAlpha=1;for(const t of this.trails){const pos=cam.toScreen(t.x,t.y-1.0);ctx.globalAlpha=.2*(t.life/t.max);ctx.fillStyle="#74e3d1";ctx.beginPath();ctx.ellipse(pos.x,pos.y,Math.max(4,cam.scale*.22),Math.max(7,cam.scale*.42),0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const p of this.particles){const pos=cam.toScreen(p.x,p.y);ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(pos.x,pos.y,Math.max(1,p.size*cam.scale),0,2*Math.PI);ctx.fill()}ctx.globalAlpha=1;for(const t of this.floaters){const pos=cam.toScreen(t.x,t.y);ctx.globalAlpha=Math.min(1,t.life/.22);ctx.font=`1000 ${Math.max(19,cam.scale*.23)}px system-ui`;ctx.textAlign='center';ctx.lineWidth=5;ctx.strokeStyle='#173e42';ctx.strokeText(t.text,pos.x,pos.y);ctx.fillStyle='#fff0a8';ctx.fillText(t.text,pos.x,pos.y)}ctx.restore()}}window.BagEffects=Effects})();
